def cutOffTree(forest: list[list[int]]) -> int:
    R, C = len(forest), len(forest[0])
    trees = []
    for r in range(R):
        for c in range(C):
            if forest[r][c] > 1:
                trees.append((forest[r][c], r, c))
    trees.sort()
    from collections import deque
    def bfs(sr, sc, tr, tc):
        if sr == tr and sc == tc: return 0
        q = deque([(sr, sc, 0)])
        visited = {(sr, sc)}
        while q:
            r, c, d = q.popleft()
            if r == tr and c == tc: return d
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and forest[nr][nc] != 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc, d + 1))
        return -1
    curr_r, curr_c = 0, 0
    total_steps = 0
    for h, tr, tc in trees:
        d = bfs(curr_r, curr_c, tr, tc)
        if d == -1: return -1
        total_steps += d
        curr_r, curr_c = tr, tc
    return total_steps

